// api.js - Axios service wrapper for TutorMatch backend
import axios from "axios";

const API_BASE = "/api"; // Or "http://localhost:8000/api" if running locally

export const registerStudent = async (studentData) => {
  const res = await axios.post(`${API_BASE}/register-student`, studentData);
  return res.data;
};

export async function getStudentProfile(id) {
  const res = await axios.get(`${BASE_URL}/student/${id}`, authHeaders());
  return res.data;
}

export async function getTutorProfile(id) {
  const res = await axios.get(`${BASE_URL}/tutor/${id}`, authHeaders());
  return res.data;
}

export const registerTutor = async (formData) => {
  const res = await axios.post(`${API_BASE}/register-tutor`, formData, {
    headers: { "Content-Type": "multipart/form-data" },
  });
  return res.data;
};

export const getStudent = async (id) => {
  const res = await axios.get(`${API_BASE}/student/${id}`);
  return res.data;
};

export const getTutor = async (id) => {
  const res = await axios.get(`${API_BASE}/tutor/${id}`);
  return res.data;
};

export const getAllMatches = async () => {
  const res = await axios.get(`${API_BASE}/matches`);
  return res.data;
};

export const triggerMatch = async (studentId) => {
  const res = await axios.post(`${API_BASE}/match/${studentId}`);
  return res.data;
};
